use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_ascii_lowercase(c: char) -> bool {
    'a' <= c && c <= 'z'
}

spec fn to_ascii_uppercase_char(c: char) -> char {
    if is_ascii_lowercase(c) {
        (c as u8 - ('a' as u8 - 'A' as u8)) as char
    } else {
        c
    }
}

spec fn to_uppercase_spec(chars: Seq<char>) -> Seq<char> {
    Seq::new(chars.len(), |i: int| to_ascii_uppercase_char(chars[i]))
}

fn to_uppercase(str1: &Vec<char>) -> (result: Vec<char>)
    ensures
        result@ == to_uppercase_spec(str1@),
        result.len() == str1.len(),
{
    let mut result_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < str1.len()
        invariant
            0 <= i <= str1.len(),
            result_vec@ == to_uppercase_spec(str1@.subrange(0, i as int)),
            result_vec.len() == i,
    {
        let c = str1[i];
        let uppercase_c = if is_ascii_lowercase(c) {
            // Convert to uppercase
            let c_u8 = c as u8;
            let a_u8 = 'a' as u8;
            let a_upper_u8 = 'A' as u8;
            let diff = a_u8 - a_upper_u8;
            let new_u8 = c_u8 - diff;
            new_u8 as char
        } else {
            c
        };
        
        result_vec.push(uppercase_c);
        i = i + 1;
    }
    
    result_vec
}

}
